export const TILE_X=27,TILE_Y=13.5;
export const project=(x,y)=>({x:(x-y)*TILE_X,y:(x+y)*TILE_Y});
export const unproject=(x,y)=>({x:(x/TILE_X+y/TILE_Y)/2,y:(y/TILE_Y-x/TILE_X)/2});
const RED='#ed4936',DARK='#9b9c8e';
function poly(c,p,f,s=null,w=1){c.beginPath();p.forEach((v,i)=>i?c.lineTo(...v):c.moveTo(...v));c.closePath();if(f){c.fillStyle=f;c.fill()}if(s){c.strokeStyle=s;c.lineWidth=w;c.stroke()}}
function line(c,p,s,w=2){c.beginPath();p.forEach((v,i)=>i?c.lineTo(...v):c.moveTo(...v));c.lineWidth=w;c.lineCap='round';c.lineJoin='round';c.strokeStyle=s;c.stroke()}
function ell(c,x,y,rx,ry,f){c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fillStyle=f;c.fill()}
export function tile(c,x,y,f,s=null){const p=[project(x,y),project(x+1,y),project(x+1,y+1),project(x,y+1)];poly(c,p.map(q=>[q.x,q.y]),f,s)}
function local(c,x,y,fn){const p=project(x,y);c.save();c.translate(p.x,p.y);fn();c.restore()}
function shadow(c,x,y,rx=40,ry=12){ell(c,x,y,rx,ry,'#67735c18')}
function tower(c,x,y,kind=0){local(c,x,y,()=>{const h=kind===1?145:115,a=[[-29,0],[9,17],[43,-1],[5,-18]];for(let i=0;i<4;i++){const j=(i+1)%4;line(c,[[a[i][0],a[i][1]],[a[i][0]-70,a[i][1]+75]],'#7b846026',2);line(c,[a[i],[a[i][0],a[i][1]-h]],RED,2.1);line(c,[[a[i][0],a[i][1]-h],[a[j][0],a[j][1]-h]],RED,2.1)}for(const z of[h*.53,h])for(let i=0;i<4;i++){const j=(i+1)%4;line(c,[[a[i][0],a[i][1]-z],[a[j][0],a[j][1]-z]],RED,2)}if(kind===2){poly(c,[[9,17-h*.53],[43,-1-h*.53],[84,42],[52,58]],RED);line(c,[[8,17-h*.53],[50,60]],'#ff7b62',2);line(c,[[43,-1-h*.53],[85,43]],'#dc362b',2)}else{const dx=kind===1?-45:0;line(c,[[-29,-h*.53],[dx-29,47]],RED,2);line(c,[[9,17-h*.53],[dx+9,64]],RED,2);for(let i=1;i<=7;i++){const t=i/8;line(c,[[-29+dx*t,-h*.53+(47+h*.53)*t],[9+dx*t,17-h*.53+(47+h*.53)*t]],RED,1.8)}if(kind===0)poly(c,[[9,17-h],[43,-1-h],[43,-1-h*.53],[9,17-h*.53]],RED)}})}
function swing(c,x,y){local(c,x,y,()=>{for(const xx of[-48,48]){line(c,[[xx-23,4],[xx,-98],[xx+26,3]],RED,2.5);line(c,[[xx-23,4],[xx-80,70]],'#7b846026',2)}line(c,[[-48,-98],[48,-98]],RED,3);for(const xx of[-22,22]){line(c,[[xx-9,-98],[xx-9,-23]],'#909584',1);line(c,[[xx+9,-98],[xx+9,-23]],'#909584',1);poly(c,[[xx-13,-24],[xx+10,-27],[xx+15,-20],[xx-9,-17]],'#838b7a')}})}
function bench(c,x,y){local(c,x,y,()=>{shadow(c,-15,15);line(c,[[-30,-4],[-30,11]],'#68705f',3);line(c,[[26,-8],[26,8]],'#68705f',3);poly(c,[[-36,-6],[20,-15],[36,-7],[-20,3]],'#969c8c');for(let i=0;i<3;i++)line(c,[[-32,-28+i*6],[24,-36+i*6]],'#89917f',4);line(c,[[-31,-30],[-31,-5]],'#6b7563',2);line(c,[[25,-37],[25,-12]],'#6b7563',2)})}
function tree(c,x,y,s=1){local(c,x,y,()=>{c.scale(s,s);shadow(c,-33,25,48,12);line(c,[[0,0],[0,-70]],'#9b9e8b',5);line(c,[[0,-33],[-16,-62]],'#9b9e8b',3);line(c,[[0,-45],[18,-71]],'#9b9e8b',3);for(let i=0;i<15;i++){const a=i*2.4,r=10+Math.sqrt(i)*7;ell(c,Math.cos(a)*r,-79+Math.sin(a)*r*.7,21,18,['#aeb7a1','#bdc3ad','#a2ad97','#c7ccb7'][i%4])}for(let i=0;i<13;i++)line(c,[[Math.sin(i*4)*27,-76+Math.cos(i*2)*19],[Math.sin(i*4)*27+2,-79+Math.cos(i*2)*19]],'#7d8c733b',1)})}
function sand(c,x,y){local(c,x,y,()=>{shadow(c,-15,15,58,15);poly(c,[[-58,-10],[-5,-36],[62,-10],[8,19]],'#d1ccba','#aeb1a0');poly(c,[[-49,-11],[-5,-29],[53,-10],[8,11]],'#e2dcc9');line(c,[[-58,-10],[8,19],[62,-10]],'#c0c4b2',5);poly(c,[[-14,-10],[-12,-25],[0,-25],[2,-10]],'#b7b6a4');ell(c,-6,-25,6,2,'#d8d1ba');line(c,[[24,-3],[30,-26]],RED,2);ell(c,31,-28,3,4,RED)})}
function building(c,x,y,w,h,z){local(c,x,y,()=>{const a=project(w,0),b=project(w,h),d=project(0,h);poly(c,[[0,0],[a.x,a.y],[a.x,a.y-z],[0,-z]],'#bdc3b1');poly(c,[[a.x,a.y],[b.x,b.y],[b.x,b.y-z],[a.x,a.y-z]],'#aab39e');poly(c,[[0,-z],[a.x,a.y-z],[b.x,b.y-z],[d.x,d.y-z]],'#d3d6c6');for(let i=1;i<Math.floor(w);i++)for(let j=0;j<2;j++){const p=project(i,.01);poly(c,[[p.x,p.y-z+14+j*25],[p.x+5,p.y-z+17+j*25],[p.x+5,p.y-z+30+j*25],[p.x,p.y-z+27+j*25]],'#7b88746b')}})}
export function makeWorld(){const out=document.createElement('canvas');out.width=2800;out.height=1700;const c=out.getContext('2d');c.scale(1.5,1.5);c.translate(920,160);
// The backdrop has no enclosing park perimeter. It can repeat into the distance.
const p=[project(0,0),project(24,0),project(24,20),project(0,20)];poly(c,p.map(q=>[q.x,q.y]),'#e3e3d3');for(let y=0;y<20;y++)for(let x=0;x<24;x++)tile(c,x,y,(x+y)%2?'#e1e2d080':'#e4e4d580','#a5aa9223');
c.save();c.setLineDash([2,7]);poly(c,p.map(q=>[q.x,q.y]),null,'#969f803d');c.restore();
// Quiet chalk games painted into the activity surface.
local(c,4,15,()=>{c.save();c.transform(1,.5,-1,.5,0,0);c.strokeStyle='#f5f4e5';c.lineWidth=2;c.beginPath();c.arc(0,0,38,0,Math.PI*2);c.stroke();c.restore()});
const objects=[[-4,0,()=>tree(c,-4,0,.9)],[-3,6,()=>tower(c,-3,6,0)],[-3,14,()=>tower(c,-3,14,1)],[-2,22,()=>bench(c,-2,22)],[5,24,()=>sand(c,5,24)],[13,24,()=>tree(c,13,24,.7)],[20,24,()=>bench(c,20,24)],[27,19,()=>tower(c,27,19,2)],[27,9,()=>swing(c,27,9)],[25,-3,()=>tree(c,25,-3,.95)],[15,-3,()=>tower(c,15,-3,1)],[7,-3,()=>bench(c,7,-3)],[-1,-6,()=>building(c,-1,-6,7,2,73)],[11,-8,()=>building(c,11,-8,4,2,94)]];
objects.sort((a,b)=>a[0]+a[1]-b[0]-b[1]);objects.forEach(o=>o[2]());
local(c,25,24,()=>{c.fillStyle='#939c85';c.font='9px monospace';c.textAlign='center';c.fillText('PLAY / TOGETHER',0,0)});return out}
export function drawDistant(c,left,top,right,bottom){const size=1700,height=1050;for(let by=Math.floor((top-300)/height);by<=Math.ceil((bottom+300)/height);by++)for(let bx=Math.floor((left-400)/size);bx<=Math.ceil((right+400)/size);bx++){if(bx===0&&by===0)continue;const xx=bx*size,yy=by*height;c.save();c.translate(xx,yy);c.globalAlpha=.7;for(const[dx,dy,k]of[[-410,60,0],[430,100,2],[20,-220,1]]){c.save();c.translate(dx,dy);tower(c,0,0,k);c.restore()}c.save();c.translate(-150,270);bench(c,0,0);c.restore();c.save();c.translate(330,-250);tree(c,0,0,.85);c.restore();c.restore()}}
export function atlasFrames(image){const cols=4,rows=3,sw=image.naturalWidth/cols,sh=image.naturalHeight/rows,off=document.createElement('canvas');off.width=image.naturalWidth;off.height=image.naturalHeight;const c=off.getContext('2d',{willReadFrequently:true});c.drawImage(image,0,0);const data=c.getImageData(0,0,off.width,off.height).data;const frames=[];for(let r=0;r<rows;r++)for(let col=0;col<cols;col++){let x0=Math.round(col*sw),y0=Math.round(r*sh),x1=Math.round((col+1)*sw),y1=Math.round((r+1)*sh),minx=x1,miny=y1,maxx=x0,maxy=y0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++){if(data[(y*off.width+x)*4+3]>40){minx=Math.min(minx,x);miny=Math.min(miny,y);maxx=Math.max(maxx,x);maxy=Math.max(maxy,y)}}frames.push({x:Math.max(x0,minx-2),y:Math.max(y0,miny-2),w:Math.min(x1,maxx+3)-Math.max(x0,minx-2),h:Math.min(y1,maxy+3)-Math.max(y0,miny-2)})}return frames}
export function drawPerson(c,p,now,size=1,alpha=1,atlas,reduced=false){c.save();c.globalAlpha=alpha;c.translate(p.wx,p.wy);shadow(c,-2,1,7,2);const pose=p.seed%12,phase=p.seed*.7;const hop=!reduced&&[3,4,9,11].includes(pose)?Math.max(0,Math.sin(now*.0025+phase))*2.2:0;const sway=reduced?0:Math.sin(now*.0016+phase)*.012;c.translate(0,-hop);c.scale(size,size);c.rotate(sway);if(atlas?.frames){const f=atlas.frames[pose],h=[5,6,7].includes(pose)?31:47,w=f.w/f.h*h;c.drawImage(atlas.image,f.x,f.y,f.w,f.h,-w/2,-h,w,h)}else{line(c,[[-3,0],[-2,-17],[2,-17],[3,0]],'#777a6e',2);poly(c,[[-5,-15],[-5,-28],[4,-28],[5,-15]],'#b3b4a3');ell(c,0,-34,5,6,'#c5c1b0');ell(c,0,-38,5,3,'#676c60')}c.restore()}
